import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import sailpoint.object.Application;
import sailpoint.object.Identity;
import sailpoint.object.Link;
import sailpoint.object.QueryOptions;
import sailpoint.object.Rule;

Rule setStatus = context.getObjectByName(Rule.class, "LDAP ApacheDS - Set Account Status");
if (setStatus == null) return "ERROR: rule 'LDAP ApacheDS - Set Account Status' not found";
Application app = context.getObjectByName(Application.class, "LDAP ApacheDS");
if (app == null) return "ERROR: application LDAP ApacheDS not found";

List names = new ArrayList();
Iterator it = context.search(Identity.class, new QueryOptions(), "name");
while (it.hasNext()) names.add(((Object[]) it.next())[0]);

StringBuilder report = new StringBuilder();
int disabled = 0;
for (Object n : names) {
    Identity id = context.getObjectByName(Identity.class, (String) n);
    if (id == null || !"Terminated".equals(id.getAttribute("status"))) continue;
    Link link = id.getLink(app);
    if (link == null) continue;
    if (Boolean.TRUE.equals(link.getAttribute("IIQDisabled")) || link.isDisabled()) continue;

    Map args = new HashMap();
    args.put("identityName", n);
    args.put("action", "Disable");
    String r = String.valueOf(context.runRule(setStatus, args));
    if (r.startsWith("DISABLED")) disabled++;
    report.append(r).append("\n");
    context.decache();
}
report.append("Done. LDAP accounts disabled: ").append(disabled);
return report.toString();
